effect.shader:
void main() {
    vec2 uv = acScreenNorm;
    vec4 src = texture2D(inputImg.texture, uv);
    float edgeDistance = min(min(uv.x, 1.0 - uv.x), min(uv.y, 1.0 - uv.y));
    float amount = strength * (1.0 - smoothstep(0.0, max(width, 0.001), edgeDistance));
    if (amount <= 0.001 || radius <= 0.0) {
        gl_FragColor = src;
        return;
    }

    vec2 stepUv = vec2(radius) / max(acScreenSize, vec2(1.0));
    vec4 blurred = src * 4.0;
    blurred += texture2D(inputImg.texture, clamp(uv + vec2( stepUv.x, 0.0), 0.0, 1.0)) * 2.0;
    blurred += texture2D(inputImg.texture, clamp(uv + vec2(-stepUv.x, 0.0), 0.0, 1.0)) * 2.0;
    blurred += texture2D(inputImg.texture, clamp(uv + vec2(0.0,  stepUv.y), 0.0, 1.0)) * 2.0;
    blurred += texture2D(inputImg.texture, clamp(uv + vec2(0.0, -stepUv.y), 0.0, 1.0)) * 2.0;
    blurred += texture2D(inputImg.texture, clamp(uv + vec2( stepUv.x,  stepUv.y), 0.0, 1.0));
    blurred += texture2D(inputImg.texture, clamp(uv + vec2(-stepUv.x,  stepUv.y), 0.0, 1.0));
    blurred += texture2D(inputImg.texture, clamp(uv + vec2( stepUv.x, -stepUv.y), 0.0, 1.0));
    blurred += texture2D(inputImg.texture, clamp(uv + vec2(-stepUv.x, -stepUv.y), 0.0, 1.0));
    gl_FragColor = mix(src, blurred / 16.0, amount);
}
